import logging
import os
from datetime import datetime
import uuid

import httpx
from fastapi.responses import JSONResponse
from databases import connection
from observability import timed_integration, log_audit

logger = logging.getLogger(__name__)

# Environment variables for Stripe
_STRIPE_SECRET_KEY = os.getenv("STRIPE_SECRET_KEY", "")
_STRIPE_API_VERSION = os.getenv("STRIPE_API_VERSION", "2023-10-16") # Default Stripe API version
_STRIPE_API_BASE = os.getenv("STRIPE_API_BASE_URL", "https://api.stripe.com/v1")
_STRIPE_HEADERS_FORM_ENCODED = {
    "Authorization": f"Bearer {_STRIPE_SECRET_KEY}",
    "Stripe-Version": _STRIPE_API_VERSION,
    "Content-Type": "application/x-www-form-urlencoded"
}
_STRIPE_HEADERS_JSON = { 
    "Authorization": f"Bearer {_STRIPE_SECRET_KEY}",
    "Stripe-Version": _STRIPE_API_VERSION,
    "Content-Type": "application/json"
}


# Helper to ensure connection is opened and closed
def _execute_sp(sp_name: str, json_file: dict, fetch_one: bool = False):
    conn = None
    cursor = None
    try:
        conn = connection()
        cursor = conn.cursor()
        cursor.execute(f"EXEC [dbo].[{sp_name}] @pjsonfile = %s", (json.dumps(json_file),))
        if fetch_one:
            row = cursor.fetchone()
            json_result = row[0] if row and row[0] else '{"message": "ok"}'
        else:
            rows = cursor.fetchall()
            json_result = "".join(row[0] for row in rows if row and row[0])
            if not json_result:
                # Return an empty JSON structure for lists, consistent with the root plural key
                return { "companyPaymentAccounts": [] }
        return json.loads(json_result)
    finally:
        try:
            if cursor: cursor.close()
        except Exception: pass
        try:
            if conn: conn.close()
        except Exception: pass

# --- CRUD Functions ---
def companyPaymentAccounts_sp(json_file: dict):
    # Extract action and primary key for auditing
    payload_list = json_file.get("companyPaymentAccounts", [])
    if not payload_list:
        return JSONResponse(content={"error": "Invalid payload format"}, status_code=400)

    payload = payload_list[0]
    action = payload.get("action")
    company_id = payload.get("companyId")
    company_payment_account_id = payload.get("companyPaymentAccountId")

    old_record = None
    if (action == 2 or action == 3) and company_payment_account_id: # UPDATE or DELETE
        # Fetch old record for auditing
        old_record_payload = {"companyId": company_id, "companyPaymentAccountId": company_payment_account_id}
        old_record_response_content = _execute_sp("sp_CompanyPaymentAccounts_one", old_record_payload, fetch_one=False)
        if old_record_response_content and old_record_response_content.get("companyPaymentAccounts"):
            old_record = old_record_response_content["companyPaymentAccounts"][0]

    try:
        result = _execute_sp("sp_CompanyPaymentAccounts", json_file, fetch_one=True)

        # Audit logging for INSERT (1), UPDATE (2), DELETE (3)
        if isinstance(result, dict) and "error" not in result:
            entity_id = company_payment_account_id # For update/delete, use existing ID
            new_record = result.get("companyPaymentAccounts", [{}])[0] if result else {}

            if action == 1: # INSERT
                entity_id = new_record.get("companyPaymentAccountId") # New ID from SP result
                log_audit("CompanyPaymentAccount", entity_id, "record", None, new_record, action=1)
            elif action == 2 and old_record: # UPDATE
                # Fields to monitor for changes for audit
                auditable_fields = [
                    "purpose", "accountType", "accountStatus", "clabe", "clabeHash",
                    "bankCode", "bankName", "holderName", "rfc", "stripeConnectedAccountId",
                    "chargesEnabled", "verifiedByUserId", "verifiedAt", "archivedAt", "notes"
                ]
                for field in auditable_fields:
                    # Check if the field was present in the update payload
                    if field in payload:
                        old_value = old_record.get(field)
                        new_value = payload.get(field) 
                        if old_value != new_value:
                            log_audit("CompanyPaymentAccount", entity_id, field, old_value, new_value, action=2)
            elif action == 3 and old_record: # DELETE
                log_audit("CompanyPaymentAccount", entity_id, "record", old_record, None, action=3)

        return JSONResponse(content=result, status_code=200)
    except Exception as e:
        logger.exception(f"[companyPaymentAccounts] Error in companyPaymentAccounts_sp: {e}")
        return JSONResponse(content={"error": str(e)}, status_code=500)


def all_companyPaymentAccounts_sp(json_file: dict):
    try:
        result = _execute_sp("sp_CompanyPaymentAccounts_all", json_file, fetch_one=False)
