# --- Connector Functions ---

async def active_companyPaymentAccount_connector(payload: dict) -> JSONResponse:
    """
    Read-only, for the client app and POS: { companyId, purpose } -> the ACTIVE spei
    (bankName, holderName, full CLABE) and whether card top-ups are available (an ACTIVE
    stripe_connect with chargesEnabled = 1). Never returns PENDING or ARCHIVED rows,
    the Stripe account id, or createdBy/verifiedBy.
    """
    try:
        result = _execute_sp("sp_CompanyPaymentAccounts_active", payload, fetch_one=False)
        return JSONResponse(content=result, status_code=200)
    except Exception as e:
        logger.exception(f"[companyPaymentAccounts] Error in active_companyPaymentAccount_connector: {e}")
        return JSONResponse(content={"error": str(e)}, status_code=500)


async def confirm_companyPaymentAccount_connector(payload: dict) -> JSONResponse:
    """
    Admin only: { companyPaymentAccountId, verifiedByUserId } -> PENDING_VERIFICATION to ACTIVE
    when verifiedByUserId != createdByUserId (and chargesEnabled = 1 for stripe_connect);
    archives the previous ACTIVE row of the same (companyId, purpose, accountType) in one transaction.
    Writes auditLogs.
    """
    company_payment_account_id = payload.get("companyPaymentAccountId")
    verified_by_user_id = payload.get("verifiedByUserId")
    company_id = payload.get("companyId") 

    if not company_payment_account_id or not verified_by_user_id or not company_id:
        return JSONResponse(content={"error": "companyPaymentAccountId, verifiedByUserId and companyId are required"}, status_code=400)

    old_record = None
    # Fetch current record for auditing before modification
    old_record_payload = {"companyId": company_id, "companyPaymentAccountId": company_payment_account_id}
    old_record_response_content = _execute_sp("sp_CompanyPaymentAccounts_one", old_record_payload, fetch_one=False)
    if old_record_response_content and old_record_response_content.get("companyPaymentAccounts"):
        old_record = old_record_response_content["companyPaymentAccounts"][0]

    try:
        result = _execute_sp("sp_CompanyPaymentAccounts_confirm", payload, fetch_one=True)

        if isinstance(result, dict) and "error" not in result:
            new_record = result.get("companyPaymentAccounts", [{}])[0] if result else {}
            # Audit the status change and verification details
            if old_record:
                if old_record.get("accountStatus") != new_record.get("accountStatus"):
                    log_audit(
                        "CompanyPaymentAccount",
                        company_payment_account_id,
                        "accountStatus",
                        old_record.get("accountStatus"),
                        new_record.get("accountStatus"),
                        action=2 # UPDATE action
                    )
                if old_record.get("verifiedByUserId") != new_record.get("verifiedByUserId"):
                    log_audit(
                        "CompanyPaymentAccount",
                        company_payment_account_id,
                        "verifiedByUserId",
                        old_record.get("verifiedByUserId"),
                        new_record.get("verifiedByUserId"),
                        action=2 # UPDATE action
                    )
                if str(old_record.get("verifiedAt")) != str(new_record.get("verifiedAt")): # Compare string representations
                    log_audit("CompanyPaymentAccount", company_payment_account_id, "verifiedAt", old_record.get("verifiedAt"), new_record.get("verifiedAt"), action=2)

            # If the new record indicates a change in chargesEnabled (e.g. from Stripe Connect webhook)
            if new_record.get("chargesEnabled") is not None and (not old_record or old_record.get("chargesEnabled") != new_record.get("chargesEnabled")):
                log_audit("CompanyPaymentAccount", company_payment_account_id, "chargesEnabled", old_record.get("chargesEnabled") if old_record else None, new_record.get("chargesEnabled"), action=2)


        return JSONResponse(content=result, status_code=200)
    except Exception as e:
        logger.exception(f"[companyPaymentAccounts] Error in confirm_companyPaymentAccount_connector: {e}")
        return JSONResponse(content={"error": str(e)}, status_code=500)


async def stripe_onboarding_link_companyPaymentAccount_connector(payload: dict) -> JSONResponse:
    """
    Admin only (worker key): creates or reuses the company's Stripe connected account
    (hand-written in modules/stripe_payments.py, the existing Connect code, keyed by
    companyId instead of clientId), stores a PENDING_VERIFICATION stripe_connect row,
    and returns the Stripe onboarding URL. The account.updated webhook refreshes chargesEnabled.
    """
    company_id = payload.get("companyId")
    created_by_user_id = payload.get("createdByUserId")
    # Optional fields from payload to pre-fill Stripe account details
    company_email = payload.get("companyEmail")
    holder_name = payload.get("holderName")
    return_url = payload.get("returnUrl", f"https://yourfrontend.com/company-payment-accounts?companyId={company_id}&status=return")
    refresh_url = payload.get("refreshUrl", f"https://yourfrontend.com/company-payment-accounts?companyId={company_id}&status=refresh")

    if not company_id or not created_by_user_id:
        return JSONResponse(content={"error": "companyId and createdByUserId are required"}, status_code=400)

    if not _STRIPE_SECRET_KEY:
        return JSONResponse(content={"error": "Stripe secret key not configured"}, status_code=500)

    stripe_account_id = None
    account_row_id = None
    existing_record = None

    # Try to find an existing PENDING_VERIFICATION or ACTIVE stripe_connect account for this company
    # Using sp_CompanyPaymentAccounts_all to find accounts that might need reuse
    filter_payload_for_existing = {
        "companyPaymentAccounts": [{
            "companyId": company_id,
            "accountType": "stripe_connect",
            "accountStatusFilter": ["ACTIVE", "PENDING_VERIFICATION"] # Assuming SP handles this filter
        }]
    }

    existing_accounts_data = _execute_sp("sp_CompanyPaymentAccounts_all", filter_payload_for_existing, fetch_one=False)
    if existing_accounts_data and existing_accounts_data.get("companyPaymentAccounts"):
        for acc in existing_accounts_data["companyPaymentAccounts"]:
            if acc.get("stripeConnectedAccountId") and acc.get("companyId") == company_id and acc.get("accountType") == "stripe_connect" and acc.get("accountStatus") in ["ACTIVE", "PENDING_VERIFICATION"]:
                stripe_account_id = acc["stripeConnectedAccountId"]
                account_row_id = acc["companyPaymentAccountId"]
                existing_record = acc
                break

    if not stripe_account_id:
        # Create a new Stripe Connected Account
        with timed_integration("Stripe", "create_account") as span:
            async with httpx.AsyncClient() as client:
                try:
                    account_params = {
                        "type": "standard", 
                        "country": "MX", 
                        "capabilities[card_payments][requested]": "true",
                        "capabilities[transfers][requested]": "true",
                        "metadata[companyId]": str(company_id),
                    }
                    if company_email:
                        account_params["email"] = company_email

                    response = await client.post(
                        f"{_STRIPE_API_BASE}/accounts",
                        headers=_STRIPE_HEADERS_FORM_ENCODED,
                        data=account_params
                    )
                    response.raise_for_status()
                    stripe_account = response.json()
                    stripe_account_id = stripe_account.get("id")
                    span.http_status = response.status_code
                    if not stripe_account_id:
                        raise ValueError("Failed to create Stripe account: No ID returned")
                except httpx.HTTPStatusError as e:
                    span.http_status = e.response.status_code
                    logger.error(f"Stripe account creation failed: {e.response.text}")
                    return JSONResponse(content={"error": f"Stripe account creation failed: {e.response.json().get('error', {}).get('message', str(e))}"}, status_code=e.response.status_code)
                except Exception as e:
                    logger.exception("Stripe account creation failed unexpectedly")
                    return JSONResponse(content={"error": f"Stripe account creation failed: {str(e)}"}, status_code=500)

        # Store the new connected account ID in dbo.CompanyPaymentAccounts
        insert_update_payload = {
            "companyPaymentAccounts": [{
                "action": 1, # INSERT a new record if stripe_account_id was just created
                "companyId": company_id,
                "purpose": payload.get("purpose", "top_ups"), 
                "accountType": "stripe_connect",
                "accountStatus": "PENDING_VERIFICATION",
                "holderName": holder_name if holder_name else "Stripe Connect Account", 
                "stripeConnectedAccountId": stripe_account_id,
                "chargesEnabled": False, 
                "createdByUserId": created_by_user_id,
            }]
        }
        persistence_result = _execute_sp("sp_CompanyPaymentAccounts", insert_update_payload, fetch_one=True)
        if persistence_result and persistence_result.get("error"):
            logger.error(f"Failed to persist Stripe connected account {stripe_account_id} to DB: {persistence_result.get('error')}")
            return JSONResponse(content={"error": f"Failed to persist Stripe account details: {persistence_result['error']}"}, status_code=500)

        account_row_id = persistence_result.get("companyPaymentAccounts", [{}])[0].get("companyPaymentAccountId")

    # Generate an Account Link for onboarding
    with timed_integration("Stripe", "create_account_link") as span:
        async with httpx.AsyncClient() as client:
            try:
                account_link_params = {
                    "account": stripe_account_id,
                    "refresh_url": refresh_url,
                    "return_url": return_url,
                    "type": "account_onboarding",
                }
                response = await client.post(
                    f"{_STRIPE_API_BASE}/account_links",
                    headers=_STRIPE_HEADERS_FORM_ENCODED,
                    data=account_link_params
                )
                response.raise_for_status()
                account_link = response.json()
                span.http_status = response.status_code

                # Fetch the full record to match response_fields, and merge onboardingUrl
                if account_row_id:
                    final_record_payload = {"companyId": company_id, "companyPaymentAccountId": account_row_id}
                    final_record_content = _execute_sp("sp_CompanyPaymentAccounts_one", final_record_payload, fetch_one=False)
                    if final_record_content and final_record_content.get("companyPaymentAccounts"):
                        final_response_data = final_record_content["companyPaymentAccounts"][0]
                        final_response_data["onboardingUrl"] = account_link.get("url")
                        return JSONResponse(content=final_response_data, status_code=200)
                    else:
                        # Fallback if fetching the new record fails, but still return URL and IDs
                        return JSONResponse(content={
                            "onboardingUrl": account_link.get("url"), 
                            "stripeConnectedAccountId": stripe_account_id, 
                            "companyPaymentAccountId": account_row_id, 
                            "warning": "Could not fetch full record after creation/update."
                        }, status_code=200)
                else:
                    return JSONResponse(content={
                        "onboardingUrl": account_link.get("url"), 
                        "stripeConnectedAccountId": stripe_account_id,
                    }, status_code=200)

            except httpx.HTTPStatusError as e:
                span.http_status = e.response.status_code
                logger.error(f"Stripe account link creation failed: {e.response.text}")
                return JSONResponse(content={"error": f"Stripe account link creation failed: {e.response.json().get('error', {}).get('message', str(e))}"}, status_code=e.response.status_code)
            except Exception as e:
                logger.exception("Stripe account link creation failed unexpectedly")
                return JSONResponse(content={"error": f"Stripe account link creation failed: {str(e)}"}, status_code=500)
