  const res = await fetch(BASE_URL + "/companyPaymentAccounts/confirm", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!res.ok) throw new Error(await res.text());
  const data = await res.json();
  return data.companyPaymentAccounts[0];
}

// CONNECTOR: Get Stripe Onboarding Link — POST /companyPaymentAccounts/stripe/onboarding-link
export async function getStripeOnboardingLink(payload: GetStripeOnboardingLinkRequest): Promise<StripeOnboardingLinkResponse> {
