    "content": "import { useCallback, useEffect, useState } from 'react';
import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged, notifyDataChanged } from '../../../utils/refreshBus';
import {
  getAllCompanyPaymentAccounts,
  createCompanyPaymentAccount,
  updateCompanyPaymentAccount,
  confirmCompanyPaymentAccount,
  getStripeOnboardingLink,
  CompanyPaymentAccount,
  CreateCompanyPaymentAccountRequest,
} from '../../../api/companyPaymentAccountApi';
import { InputInputEventDetail, SelectChangeEventDetail } from '@ionic/core';

export type AccountPurposeType = 'top_ups'; // Extend as needed
export type AccountType = 'spei' | 'stripe_connect';
export type AccountStatus = 'PENDING_VERIFICATION' | 'ACTIVE' | 'ARCHIVED';

export interface NewClabeFormState extends Omit<CreateCompanyPaymentAccountRequest, 'accountType' | 'accountStatus'> {
  clabeError: string | null;
  bankNameError: string | null; // bankName is auto-filled but should be valid if manual
  holderNameError: string | null;
  rfcError: string | null;
  purposeError: string | null;
  globalError: string | null;
}

const initialNewClabeFormState: NewClabeFormState = {
  clabe: '',
  bankCode: null,
  bankName: null,
  holderName: '',
  rfc: null,
  purpose: 'top_ups', // Default purpose
  notes: null,
  createdByUserId: 0, // Will be set by useUser()
  clabeError: null,
  bankNameError: null,
  holderNameError: null,
  rfcError: null,
  purposeError: null,
  globalError: null,
};

const BANK_CATALOG: Record<string, string> = {
  '002': 'BANAMEX',
  '012': 'BBVA BANCOMER',
  '014': 'SANTANDER',
  // Add more banks as needed
};

const validateClabe = (clabe: string): { isValid: boolean; bankCode: string | null; bankName: string | null; error: string | null } => {
  if (!clabe || clabe.length !== 18 || !/^[0-9]+$/.test(clabe)) {
    return { isValid: false, bankCode: null, bankName: null, error: 'La CLABE debe ser numérica y tener 18 dígitos.' };
  }

  const bankCode = clabe.substring(0, 3);
  const bankName = BANK_CATALOG[bankCode] || null;

  // Basic check digit validation (Luhn algorithm or Modulo 10 for CLABE not strictly used for all CLABEs client side, simplified)
  // A full CLABE validation involves a modulo 10 check, but for client-side, length and numeric is a good start.
  // This example skips the full modulo 10 calculation as it's complex and usually handled by an external library or backend.

  return {
    isValid: !!bankName,
    bankCode,
    bankName,
    error: bankName ? null : 'Código de banco no reconocido.'
  };
};

export const useCompanyPaymentAccount = () => {
  const { companyId, userId, roleCode } = useUser();
  const { showToast, toastProps } = useToast();
  const [accounts, setAccounts] = useState<CompanyPaymentAccount[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [showNewClabeModal, setShowNewClabeModal] = useState(false);
  const [newClabeForm, setNewClabeForm] = useState<NewClabeFormState>(initialNewClabeFormState);
  const [showConfirmAccountSheet, setShowConfirmAccountSheet] = useState(false);
  const [selectedAccountForConfirm, setSelectedAccountForConfirm] = useState<CompanyPaymentAccount | null>(null);
  const [stripeOnboardingLoading, setStripeOnboardingLoading] = useState(false);
  const [stripeOnboardingUrl, setStripeOnboardingUrl] = useState<string | null>(null);
  const [showArchived, setShowArchived] = useState<Record<AccountPurposeType, boolean>>({ top_ups: false }); // Extend default purposes

  const availablePurposes: AccountPurposeType[] = ['top_ups']; // Define all possible purposes

  const loadAccounts = useCallback(async () => {
    if (!companyId) return;
    setLoading(true);
    try {
      const fetchedAccounts = await getAllCompanyPaymentAccounts(companyId);
      setAccounts(fetchedAccounts);
    } catch (err) {
      showToast((err as Error).message ?? 'Error al cargar cuentas de cobro', 'danger');
    }
    setLoading(false);
  }, [companyId, showToast]);

  useEffect(() => {
    loadAccounts();
  }, [loadAccounts]);

  useIonViewWillEnter(() => {
    loadAccounts();
  });

  useEffect(() => {
    const unsubscribe = onDataChanged('companyPaymentAccount-saved', () => {
      loadAccounts();
    });
    return () => unsubscribe();
  }, [loadAccounts]);

  const accountsByPurpose: Record<AccountPurposeType, CompanyPaymentAccount[]> = availablePurposes.reduce((acc, purpose) => {
    acc[purpose] = accounts.filter(acc => acc.purpose === purpose).sort((a,b) => {
      if (a.accountStatus === 'ACTIVE' && b.accountStatus !== 'ACTIVE') return -1;
      if (a.accountStatus !== 'ACTIVE' && b.accountStatus === 'ACTIVE') return 1;
      if (a.accountStatus === 'PENDING_VERIFICATION' && b.accountStatus !== 'PENDING_VERIFICATION') return -1;
      if (a.accountStatus !== 'PENDING_VERIFICATION' && b.accountStatus === 'PENDING_VERIFICATION') return 1;
      return new Date(b.created_At).getTime() - new Date(a.created_At).getTime();
    });
    return acc;
  }, {} as Record<AccountPurposeType, CompanyPaymentAccount[]>);

  const openNewClabeModal = (purpose: AccountPurposeType) => {
    setNewClabeForm({ ...initialNewClabeFormState, createdByUserId: userId, purpose: purpose });
    setShowNewClabeModal(true);
  };

  const closeNewClabeModal = () => {
    setShowNewClabeModal(false);
    setNewClabeForm(initialNewClabeFormState);
  };

  const handleNewClabeFormChange = (field: keyof NewClabeFormState, value: string) => {
    setNewClabeForm(prev => {
      let newState = { ...prev, [field]: value, [`${field}Error`]: null, globalError: null };

      if (field === 'clabe') {
        const { isValid, bankCode, bankName, error } = validateClabe(value);
        newState.clabeError = error;
        newState.bankCode = bankCode;
        newState.bankName = bankName;
      }
      // Basic validation for holderName and RFC
      if (field === 'holderName' && !value.trim()) {
        newState.holderNameError = 'El nombre del titular es requerido.';
      }
      if (field === 'rfc' && value.trim() && (value.length < 12 || value.length > 13)) {
        newState.rfcError = 'El RFC debe tener 12 o 13 caracteres.';
      }
      return newState;
    });
  };

  const isNewClabeFormValid = (
    newClabeForm.clabe.length === 18 &&
    !newClabeForm.clabeError &&
    newClabeForm.bankName &&
    newClabeForm.holderName.trim() !== '' &&
    !newClabeForm.holderNameError &&
    !newClabeForm.rfcError &&
    newClabeForm.purpose.trim() !== ''
  );

  const handleCreateClabe = async () => {
    if (!isNewClabeFormValid) {
      setNewClabeForm(prev => ({ ...prev, globalError: 'Por favor, corrige los errores del formulario.' }));
      return;
    }

    setSaving(true);
    try {
      const payload: CreateCompanyPaymentAccountRequest = {
        companyId,
        purpose: newClabeForm.purpose,
        accountType: 'spei',
        accountStatus: 'PENDING_VERIFICATION',
        clabe: newClabeForm.clabe,
        bankCode: newClabeForm.bankCode,
        bankName: newClabeForm.bankName,
        holderName: newClabeForm.holderName,
        rfc: newClabeForm.rfc,
        notes: newClabeForm.notes,
        createdByUserId: userId,
      };

      await createCompanyPaymentAccount(payload);
      notifyDataChanged('companyPaymentAccount-saved');
      showToast('CLABE registrada con éxito. Requiere confirmación.', 'success');
      closeNewClabeModal();
    } catch (err) {
      setNewClabeForm(prev => ({ ...prev, globalError: (err as Error).message ?? 'Error al registrar CLABE.' }));
      showToast((err as Error).message ?? 'Error al registrar CLABE.', 'danger');
    }
    setSaving(false);
  };

  const openConfirmAccountSheet = (account: CompanyPaymentAccount) => {
    setSelectedAccountForConfirm(account);
    setShowConfirmAccountSheet(true);
  };

  const closeConfirmAccountSheet = () => {
    setShowConfirmAccountSheet(false);
    setSelectedAccountForConfirm(null);
  };

  const handleConfirmAccount = async () => {
    if (!selectedAccountForConfirm) return;
    setSaving(true);
    try {
      await confirmCompanyPaymentAccount({
        companyPaymentAccountId: selectedAccountForConfirm.companyPaymentAccountId,
        verifiedByUserId: userId,
        companyId: companyId,
      });
      notifyDataChanged('companyPaymentAccount-saved');
      showToast('Cuenta confirmada y activada con éxito.', 'success');
      closeConfirmAccountSheet();
    } catch (err) {
      showToast((err as Error).message ?? 'Error al confirmar la cuenta', 'danger');
    }
    setSaving(false);
  };

  const handleConnectStripe = async (purpose: AccountPurposeType) => {
    setStripeOnboardingLoading(true);
    try {
      const payload = {
        companyId,
        createdByUserId: userId,
        purpose,
        // Add optional fields like companyEmail, holderName from the company profile if available
        returnUrl: `${window.location.origin}/company-payment-accounts`,
        refreshUrl: `${window.location.origin}/company-payment-accounts`,
      };
      const res = await getStripeOnboardingLink(payload);
      if (res.onboardingUrl) {
        setStripeOnboardingUrl(res.onboardingUrl);
        // Open URL in new window/tab, or use an Ionic InAppBrowser plugin for native feel
        // window.open(res.onboardingUrl, '_system'); // _system for native browser
        // The IonModal will handle displaying the link and opening it.
      } else {
        showToast('No se pudo obtener el enlace de onboarding de Stripe.', 'danger');
      }
    } catch (err) {
      showToast((err as Error).message ?? 'Error al conectar con Stripe', 'danger');
    }
    setStripeOnboardingLoading(false);
  };

  const handleRefresh = async (event: CustomEvent<void>) => {
    await loadAccounts();
    (event.target as HTMLIonRefresherElement).complete();
  };

  const toggleArchived = (purpose: AccountPurposeType) => {
    setShowArchived(prev => ({ ...prev, [purpose]: !prev[purpose] }));
  };

  const activeAccounts = accounts.filter(acc => acc.accountStatus === 'ACTIVE');

  return {
    accounts,
    accountsByPurpose,
    loading,
    saving,
    toastProps,
    showNewClabeModal,
    openNewClabeModal,
    closeNewClabeModal,
    newClabeForm,
    handleNewClabeFormChange,
    isNewClabeFormValid,
    handleCreateClabe,
    showConfirmAccountSheet,
    openConfirmAccountSheet,
    closeConfirmAccountSheet,
    selectedAccountForConfirm,
    handleConfirmAccount,
    stripeOnboardingLoading,
    stripeOnboardingUrl,
    setStripeOnboardingUrl,
    handleConnectStripe,
    handleRefresh,
    toggleArchived,
    showArchived,
    availablePurposes,
    userId,
    activeAccounts,
  };
};

